begin;
create extension if not exists pgtap with schema extensions;
set local search_path=public,extensions;
select plan(48);
insert into auth.users(id,email,raw_user_meta_data) values
('31000000-0000-4000-8000-000000000001','phase3-a@example.invalid','{}'),
('31000000-0000-4000-8000-000000000002','phase3-b@example.invalid','{}'),
('31000000-0000-4000-8000-000000000003','phase3-c@example.invalid','{}');
create temporary table character_results(label text primary key,value jsonb);grant all on character_results to authenticated;
insert into character_results values('look',public._default_character(1));
set local role authenticated;
set local request.jwt.claims='{"sub":"31000000-0000-4000-8000-000000000001","role":"authenticated"}';
select throws_ok($$select public.get_house_characters()$$,'42501',null,'Unpaired caller has no character snapshot');
insert into character_results values('create',public.create_couple(gen_random_uuid())),('snapshot',public.get_house_snapshot());
select is(public.get_house_characters()->'profiles'->0->>'configured','false','Onboarding defaults are not saved appearances');
select throws_ok($$insert into public.character_appearances(user_id,appearance) values(auth.uid(),'{}')$$,'42501',null,'Direct appearance writes denied');
select throws_ok($$insert into public.character_outfits values(auth.uid(),0,'{}')$$,'42501',null,'Direct outfit writes denied');
select throws_ok($$delete from public.character_social$$,'42501',null,'Direct consent writes denied');
select throws_ok($$select public._valid_appearance('{}')$$,'42501',null,'Private helper cannot be invoked by client');
select is(public.save_character('{}',null,gen_random_uuid())->>'code','INVALID_APPEARANCE','Missing catalog selections refused');
select is(public.save_character((select value||'{"skin":8}' from character_results where label='look'),null,gen_random_uuid())->>'code','INVALID_APPEARANCE','Out of catalog skin refused');
select is(public.save_character((select value||'{"height":1.5}' from character_results where label='look'),null,gen_random_uuid())->>'code','INVALID_APPEARANCE','Fractional catalog selections refused');
select is(public.save_character((select value from character_results where label='look'),5,gen_random_uuid())->>'code','INVALID_APPEARANCE','Sixth preset refused');
insert into character_results values('saved',public.save_character((select value from character_results where label='look'),null,'32000000-0000-4000-8000-000000000001'));
select is((select value->>'ok' from character_results where label='saved'),'true','Own appearance saves');
select is(public.save_character((select value from character_results where label='look'),null,'32000000-0000-4000-8000-000000000001'),(select value from character_results where label='saved'),'Duplicate save replays');
select is(public.save_character((select value||'{"skin":2}' from character_results where label='look'),null,'32000000-0000-4000-8000-000000000001')->>'code','REQUEST_CONFLICT','Duplicate key cannot change appearance');
select is(public.get_house_characters()->'profiles'->0->>'configured','true','Appearance read is authoritative');
select public.save_character((select value from character_results where label='look'),s,gen_random_uuid()) from generate_series(0,4) s;
select is(jsonb_array_length(public.get_house_characters()->'presets'),5,'Five owned outfits persist');
select is(public.character_action('request','hug',null,'33000000-0000-4000-8000-000000000001',1040,736,gen_random_uuid())->>'code','NO_PARTNER','Pending couple cannot request physical actions');
set local request.jwt.claims='{"sub":"31000000-0000-4000-8000-000000000002","role":"authenticated"}';
select public.join_couple((select value->'invite'->>'code' from character_results where label='snapshot'),gen_random_uuid());
select is((select count(*)::integer from public.character_appearances),1,'Partner reads saved look');
select is((select count(*)::integer from public.character_outfits),0,'Partner cannot read private presets');
set local request.jwt.claims='{"sub":"31000000-0000-4000-8000-000000000001","role":"authenticated"}';
select is(public.character_action('request','hug',null,'33000000-0000-4000-8000-000000000001','NaN'::float8,736,gen_random_uuid())->>'code','OUT_OF_RANGE','Nonfinite request refused');
select is(public.character_action('request','cuddle',null,'33000000-0000-4000-8000-000000000001',1040,736,gen_random_uuid())->>'code','NEED_SEATS','Cuddle needs occupied paired furniture');
insert into character_results values('hug',public.character_action('request','hug',null,'33000000-0000-4000-8000-000000000001',1040,736,'34000000-0000-4000-8000-000000000001'));
select is((select value->>'ok' from character_results where label='hug'),'true','Hug request succeeds');
select is(public.character_action('request','hug',null,'33000000-0000-4000-8000-000000000001',1040,736,'34000000-0000-4000-8000-000000000001'),(select value from character_results where label='hug'),'Duplicate request replays');
select is(public.character_action('accept',null,'34000000-0000-4000-8000-000000000001','33000000-0000-4000-8000-000000000001',1040,736,gen_random_uuid())->>'code','NOT_OWNER','Sender cannot accept own request');
set local request.jwt.claims='{"sub":"31000000-0000-4000-8000-000000000002","role":"authenticated"}';
select is(public.character_action('request','hug',null,'33000000-0000-4000-8000-000000000002',1040,760,gen_random_uuid())->>'code','BUSY','Simultaneous opposite request refused');
select is(public.character_action('accept',null,'34000000-0000-4000-8000-000000000001','33000000-0000-4000-8000-000000000002',256,1200,gen_random_uuid())->>'code','OUT_OF_RANGE','Distant acceptance refused');
select is(public.character_action('accept',null,'34000000-0000-4000-8000-000000000001','33000000-0000-4000-8000-000000000002',1040,760,gen_random_uuid())->>'ok','true','Near recipient accepts');
select is(public.get_house_characters()->'social'->>'status','active','Both read authoritative paired activity');
select is(public.house_interact('start','sofa','0','33000000-0000-4000-8000-000000000002',256,1200,gen_random_uuid())->>'code','ALREADY_USING','Accepted action prevents new furniture activity');
select is(public.character_action('cancel',null,'34000000-0000-4000-8000-000000000001',gen_random_uuid(),1040,760,gen_random_uuid())->>'code','NOT_OWNER','Wrong session cannot cancel');
select is(public.character_action('cancel',null,'34000000-0000-4000-8000-000000000001','33000000-0000-4000-8000-000000000002',1040,760,gen_random_uuid())->>'ok','true','Recipient can cancel');
select ok(public.get_house_characters()->'social'='null'::jsonb,'Cancellation removes action for both');
select public.character_action('request','hug',null,'33000000-0000-4000-8000-000000000002',1040,760,'34000000-0000-4000-8000-000000000002');
reset role;
update public.character_social set expires_at=now()-interval '1 second' where id='34000000-0000-4000-8000-000000000002';
set local role authenticated;
set local request.jwt.claims='{"sub":"31000000-0000-4000-8000-000000000001","role":"authenticated"}';
select is(public.character_action('accept',null,'34000000-0000-4000-8000-000000000002','33000000-0000-4000-8000-000000000001',1040,736,gen_random_uuid())->>'code','EXPIRED','Expired request cannot be accepted');
select is(public.house_interact('start','sofa','0','33000000-0000-4000-8000-000000000001',256,1200,gen_random_uuid())->>'ok','true','Sender occupies sofa');
set local request.jwt.claims='{"sub":"31000000-0000-4000-8000-000000000002","role":"authenticated"}';
select is(public.house_interact('start','sofa','1','33000000-0000-4000-8000-000000000002',256,1200,gen_random_uuid())->>'ok','true','Recipient occupies other sofa slot');
set local request.jwt.claims='{"sub":"31000000-0000-4000-8000-000000000001","role":"authenticated"}';
select is(public.character_action('request','hug',null,'33000000-0000-4000-8000-000000000001',256,1200,gen_random_uuid())->>'code','BUSY','Hug cannot displace seated players');
select is(public.character_action('request','cuddle',null,'33000000-0000-4000-8000-000000000001',256,1200,'34000000-0000-4000-8000-000000000003')->>'ok','true','Same sofa permits Cuddle request');
set local request.jwt.claims='{"sub":"31000000-0000-4000-8000-000000000002","role":"authenticated"}';
select is(public.character_action('accept',null,'34000000-0000-4000-8000-000000000003',gen_random_uuid(),256,1200,gen_random_uuid())->>'code','NEED_SEATS','Cuddle acceptance binds actual seat session');
select is(public.character_action('accept',null,'34000000-0000-4000-8000-000000000003','33000000-0000-4000-8000-000000000002',256,1200,gen_random_uuid())->>'ok','true','Both seats accept Cuddle');
select is(public.get_house_characters()->'social'->>'object_id','sofa','Cuddle retains furniture anchor');
select is(public.character_action('renew',null,'34000000-0000-4000-8000-000000000003','33000000-0000-4000-8000-000000000002',256,1200,gen_random_uuid())->>'ok','true','Own active lease renews');
select is(public.house_interact('cancel',null,null,'33000000-0000-4000-8000-000000000002',256,1200,gen_random_uuid())->>'ok','true','Furniture Leave succeeds');
select ok(public.get_house_characters()->'social'='null'::jsonb,'Furniture Leave also ends paired action atomically');
select is(public.character_action('renew',null,'34000000-0000-4000-8000-000000000003','33000000-0000-4000-8000-000000000002',256,1200,gen_random_uuid())->>'code','EXPIRED','Renew cannot resurrect canceled Cuddle');
set local request.jwt.claims='{"sub":"31000000-0000-4000-8000-000000000001","role":"authenticated"}';
select public.house_interact('cancel',null,null,'33000000-0000-4000-8000-000000000001',256,1200,gen_random_uuid());
set local request.jwt.claims='{"sub":"31000000-0000-4000-8000-000000000001","role":"authenticated"}';
select public.character_action('request','hug',null,'33000000-0000-4000-8000-000000000001',1040,736,'34000000-0000-4000-8000-000000000004');
set local request.jwt.claims='{"sub":"31000000-0000-4000-8000-000000000002","role":"authenticated"}';
select is(public.character_action('ignore',null,'34000000-0000-4000-8000-000000000004','33000000-0000-4000-8000-000000000002',1040,760,gen_random_uuid())->>'ok','true','Recipient can ignore');
select ok(public.get_house_characters()->'social'='null'::jsonb,'Ignore clears pending request');
set local request.jwt.claims='{"sub":"31000000-0000-4000-8000-000000000003","role":"authenticated"}';
select is((select count(*)::integer from public.character_appearances),0,'Other couple cannot read appearances');
select is((select count(*)::integer from public.character_social),0,'Other couple cannot read actions');
set local role anon;set local request.jwt.claims='{"role":"anon"}';
select throws_ok($$select public.save_character('{}',null,gen_random_uuid())$$,'42501',null,'Anonymous mutation denied');
select * from finish();
rollback;
